                  fontSize: 11,
                  fontWeight: 700,
                  letterSpacing: "0.18em",
                  textTransform: "uppercase",
                  color: "#c8a96e",
                  textDecoration: "none",
                  transition: "color 0.3s ease, transform 0.3s ease",
