  if (props.variant === "hair-03-navbar") return <NavbarHair03 {...props} />;
  if (props.variant === "hair-04-navbar") return <NavbarHair04 {...props} />;
  if (props.variant === "beauty-01-topbar") return <NavbarBeauty01 {...props} />;
