  // Topbar kontakt — editovatelné
  const topPhone   = String(content.phone   ?? "704 123 456");
  const topAddress = String(content.address ?? "Ukázková 123, 110 00 Praha 1");
  const topHours   = String(content.hours   ?? "Po–Pá 9–18 · So 9–14");
  const facebook   = String(content.facebook  ?? "https://facebook.com/demo");
  const instagram  = String(content.instagram ?? "https://instagram.com/demo");

  const logoSrc = logoUrl || "/templates/tattoo-02/logo.svg";
